css:
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;700&family=Noto+Naskh+Arabic:wght@400;700&family=Ubuntu:wght@400;700&display=swap');
@page { size: A4; margin: 10mm; }
body { margin: 0; padding: 0; color: #333; }
.page { width: 190mm; margin: 0 auto; page-break-after: always; }
.header { border-bottom: 2px solid #07417b; padding: 10px 0; display: table; width: 100%; }
.header .logo-cell { display: table-cell; width: 25%; vertical-align: middle; }
.header .logo-cell img { max-width: 110px; }
.header .name-cell { display: table-cell; width: 75%; vertical-align: middle; text-align: right; }
.title-en { text-align: center; font-weight: bold; margin: 20px 0 10px; }
.title-ar { text-align: center; font-family: 'Noto Naskh Arabic', serif; font-weight: 700; margin: 5px 0 20px; direction: rtl; }
.section { margin: 15px 0; }
.section h3 { border-bottom: 1px solid #ccc; padding-bottom: 5px; }
.bilingual { display: table; width: 100%; }
.bilingual .left { display: table-cell; width: 50%; text-align: left; vertical-align: top; }
.bilingual .right { display: table-cell; width: 50%; text-align: right; direction: rtl; vertical-align: top; }
table.passengers { width: 100%; border-collapse: collapse; margin: 10px 0; }
table.passengers th { background: #07417b; color: #fff; padding: 6px 8px; text-align: left; }
table.passengers th.ar-th { text-align: right; direction: rtl; }
table.passengers td { padding: 6px 8px; border-bottom: 1px solid #eee; }
table.passengers tr:nth-child(even) { background: #f9fafb; }
.tc { direction: rtl; text-align: right; line-height: 2; }
.tc h3 { font-family: 'Noto Naskh Arabic', serif; }
.signature-area { margin-top: 40px; display: table; width: 100%; }
.signature-area .party { display: table-cell; width: 45%; vertical-align: top; text-align: center; }
.signature-area .party .line { border-top: 1px solid #333; width: 80%; margin: 40px auto 5px; padding-top: 5px; }
.footer { text-align: center; margin-top: 20px; border-top: 1px solid #ccc; padding-top: 10px; font-size: 9pt; color: #666; }

html:
{% set company_doc = frappe.get_doc('Company', doc.company) %}
{% set company_en = company_doc.company_name or doc.company %}
{% set company_ar = company_doc.company_name_arabic or company_en %}
{% set company_phone = company_doc.phone_no or company_doc.phone or '' %}
{% set reg_no = company_doc.registration_details or company_doc.cr_no or '' %}
{% set veh = frappe.get_doc('Vehicle', doc.vehicle) if doc.vehicle else None %}
{% set first = doc.passengers[0] if doc.passengers else None %}
{% set code = doc.trip_code or doc.name %}
{% set gregorian = frappe.utils.formatdate(doc.trip_date, 'dd-MM-yyyy') if doc.trip_date else '' %}

<style>
  @page { size: A4; margin: 0; }
  body { margin: 0; }
  .sheet { padding: 34px 44px 40px 44px; color: #111; font-family: 'Ubuntu', 'Amiri', sans-serif; font-size: 10.5pt; box-sizing: border-box; min-height: 1000px; }
  .top { display: flex; justify-content: space-between; align-items: flex-start; }
  .logo { width: 84px; height: 84px; border: 1px solid #ddd; border-radius: 16px; display: flex; align-items: center; justify-content: center; overflow: hidden; background: #fff; }
  .logo img { max-width: 80px; max-height: 80px; }
  .logo span { font-weight: 700; font-size: 20pt; color: #07417b; }
  .head-mid { flex: 1; padding-left: 18px; }
  .kicker { font-size: 9pt; letter-spacing: 3px; color: #666; font-weight: 700; }
  .code { font-size: 24pt; font-weight: 800; margin: 2px 0; }
  .company { font-size: 11pt; font-weight: 700; color: #333; }
  .company-ar { font-family: 'Amiri', serif; font-size: 13pt; direction: rtl; text-align: left; color: #333; }
  .head-right { text-align: right; width: 210px; }
  .status { font-size: 13pt; font-weight: 800; color: #5b8a3a; letter-spacing: 2px; }
  .gen { font-size: 9pt; font-weight: 700; margin-top: 6px; }
  .qr img { width: 118px; height: 118px; margin-top: 6px; }
  .rule { border-top: 3px solid #111; margin: 16px 0 14px 0; }
  .route { border: 1px solid #ddd; border-radius: 18px; padding: 16px 22px; display: flex; justify-content: space-between; align-items: center; }
  .route .lbl { font-size: 9pt; letter-spacing: 3px; font-weight: 700; color: #555; }
  .route .place { font-size: 15pt; font-weight: 800; margin-top: 4px; }
  .route .place-ar { font-family: 'Amiri', serif; font-size: 13pt; font-weight: 700; direction: rtl; }
  .arrow { font-size: 22pt; color: #999; padding: 0 16px; }
  .sec { font-size: 11pt; font-weight: 800; letter-spacing: 3px; margin: 18px 0 8px 0; }
  .grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
  .card { border: 1px solid #ddd; border-radius: 12px; padding: 9px 11px; min-height: 42px; }
  .card .k { font-size: 8pt; letter-spacing: 2px; font-weight: 700; color: #555; }
  .card .v { font-size: 11pt; font-weight: 800; margin-top: 4px; }
  table.pm { width: 100%; border-collapse: collapse; font-size: 9.5pt; }
  table.pm th { text-align: left; font-size: 8pt; letter-spacing: 1.5px; color: #777; padding: 6px 5px; border-bottom: 1px solid #ddd; }
  table.pm td { padding: 7px 5px; border-bottom: 1px solid #eee; font-weight: 700; vertical-align: top; }
  .sign { display: flex; justify-content: space-between; margin-top: 60px; }
  .sign div { width: 44%; border-top: 2px solid #111; padding-top: 6px; text-align: center; font-weight: 700; font-size: 10pt; }
  .page2 { page-break-before: always; }
  .ag-head { text-align: center; }
  .ag-kicker { font-size: 10pt; letter-spacing: 2px; color: #555; font-weight: 700; }
  .ag-company { font-size: 15pt; font-weight: 800; margin-top: 4px; }
  .ag-sub { font-size: 10pt; margin-top: 2px; }
  .ag-body { font-family: 'Amiri', 'Noto Naskh Arabic', serif; font-size: 13pt; line-height: 2; direction: rtl; text-align: right; margin-top: 14px; }
  .ag-body h3 { font-size: 13pt; margin: 14px 0 4px 0; }
  .ag-title { text-align: center; font-size: 19pt; font-weight: 800; margin: 18px 0 8px 0; }
  .ag-route { border: 1px solid #ddd; border-radius: 12px; padding: 10px 16px; margin: 12px 0; }
  .ftr2 { margin-top: 28px; border-top: 1px solid #ccc; padding-top: 8px; text-align: center; font-size: 9pt; color: #333; }
</style>

<div class="sheet">
  <div class="top">
    <div class="logo">
      {% if company_doc.company_logo %}<img src="{{ company_doc.company_logo | abs_url }}" alt="Logo">{% else %}<span>{{ (company_en or 'T')[:1] }}</span>{% endif %}
    </div>
    <div class="head-mid">
      <div class="kicker">TRIP MANIFEST</div>
      <div class="code">{{ code }}</div>
      <div class="company">{{ company_en }}</div>
    </div>
    <div class="head-right">
      <div class="status">{{ (doc.trip_status or 'Draft') | upper }}</div>
      <div class="gen">Generated: {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), 'MMM dd, yyyy, hh:mm a') }}</div>
      <div class="qr">{% if doc.qr_code %}<img src="{{ doc.qr_code }}" alt="QR">{% endif %}</div>
    </div>
  </div>

  <div class="rule"></div>

  <div class="route">
    <div>
      <div class="lbl">FROM</div>
      <div class="place">{{ doc.from_location or '-' }}</div>
    </div>
    <div class="arrow">→</div>
    <div style="text-align:right;">
      <div class="lbl">TO</div>
      <div class="place">{{ doc.to_location or '-' }}</div>
    </div>
  </div>

  <div class="sec">TRIP DETAILS</div>
  <div class="grid">
    <div class="card"><div class="k">DATE</div><div class="v">{{ gregorian or '-' }}</div></div>
    <div class="card"><div class="k">DRIVER</div><div class="v">{{ doc.driver or '-' }}</div></div>
    <div class="card"><div class="k">VEHICLE TYPE</div><div class="v">{{ (veh.vehicle_type if veh else '') or (veh.vehicle_name if veh else '') or '-' }}</div></div>
    <div class="card"><div class="k">REGISTRATION NO</div><div class="v">{{ (veh.registration_no if veh else '') or (veh.plate_no if veh else '') or '-' }}</div></div>
    <div class="card"><div class="k">PASSENGERS</div><div class="v">{{ doc.passenger_count or (doc.passengers | length) }}</div></div>
    <div class="card"><div class="k">DEPARTURE</div><div class="v">{{ doc.actual_departure_datetime or doc.departure_datetime or '-' }}</div></div>
    <div class="card"><div class="k">ARRIVAL</div><div class="v">{{ doc.actual_arrival_datetime or doc.planned_arrival_datetime or '-' }}</div></div>
    <div class="card"><div class="k">DISTANCE</div><div class="v">{{ doc.distance_km or '-' }} km</div></div>
    <div class="card"><div class="k">CO-DRIVER</div><div class="v">{{ doc.co_driver or '-' }}</div></div>
  </div>

  <div class="sec">PASSENGER MANIFEST</div>
  <table class="pm">
    <thead>
      <tr><th style="width:5%">#</th><th style="width:33%">PASSENGER NAME</th><th style="width:14%">DOC TYPE</th><th style="width:18%">ID / DOCUMENT</th><th style="width:15%">NATIONALITY</th><th>MOBILE</th></tr>
    </thead>
    <tbody>
      {% for p in doc.passengers %}
      <tr>
        <td>{{ loop.index }}</td>
        <td>{{ p.passenger_name or '' }}</td>
        <td>{{ p.document_type or '' }}</td>
        <td>{{ p.document_number or '' }}</td>
        <td>{{ p.nationality or '' }}</td>
        <td>{{ p.mobile_no or '' }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <div class="sign">
    <div>{{ doc.driver or '' }}<br><span style="font-family:'Amiri',serif;">السائق</span></div>
    <div>Operations Approval</div>
  </div>
</div>

<div class="page2 sheet">
  <div class="ag-head">
    <div class="ag-kicker">TRIP AGREEMENT &nbsp;|&nbsp; <span style="font-family:'Amiri',serif;">اتفاقية الرحلة</span></div>
    <div class="ag-company">{{ company_en }}</div>
    <div class="ag-sub">{{ company_ar }}</div>
    <div class="ag-sub">رقم الرحلة: {{ code }}</div>
  </div>
  <hr style="border:none;border-top:2px solid #111;margin:12px 0;">

  <div class="ag-body">
    <p><strong>التاريخ الهجري:</strong> {{ doc.hijri_date or '' }} هـ</p>
    <p><strong>الميلادي:</strong> {{ gregorian }} م</p>

    <div class="ag-title">عقد نقل ركاب بالحافلات</div>

    <p>تم إبرام هذا العقد بين:</p>
    <p><strong>الطرف الأول :</strong> {{ company_ar }}</p>
    <p><strong>الطرف الثاني :</strong> {% if first and first.passenger_name %}{{ first.passenger_name }}{% else %}____________{% endif %}</p>

    <h3>بناءً على:</h3>
    <p>المادة (39) من اللائحة المنظمة لنشاط النقل البري للركاب وتوجيه الحافلات.</p>
    <p>المادة (1) من المادة (39) التي تنص على وجوب إبرام الناقل لعقد نقل مع الأطراف التجارية الأخرى.</p>

    <h3>اتفق الطرفان على ما يلي:</h3>
    <p><strong>موضوع العقد :</strong></p>
    <ul>
      <li>يتعهد الطرف الأول بتنفيذ عملية نقل للطرف الثاني، مع مراقبة وتوجيه الركاب من الموقع المحدد مسبقًا، وتوصيلهم إلى الوجهة المحددة في هذا العقد.</li>
    </ul>

    <div class="ag-route">
      <p><strong>نقطة الانطلاق :</strong> {{ doc.from_location or '' }}</p>
      <p><strong>نقطة الوصول :</strong> {{ doc.to_location or '' }}</p>
    </div>

    <h3>سياسة الإلغاء والاستبدال :</h3>
    <p>في حال كان التعاقد بين شخصين أو لأسباب أخرى تتعلق بالحجوزات أو الأنظمة، تخضع سياسة الإلغاء والاستبدال للأحكام نظام وزارة التجارة السعودية. وفي حالة إلغاء الحجز قبل موعد الرحلة بأكثر من 24 ساعة، يتم استرداد المبلغ بالكامل.</p>
  </div>

  <div class="ftr2">الهاتف: {{ company_phone or '-' }} &nbsp;|&nbsp; رقم التسجيل: {{ reg_no or '-' }}</div>
</div>

{% set insp_rows = frappe.get_all("Vehicle Inspection Log", filters={"vehicle": doc.vehicle, "inspection_date": doc.trip_date}, fields=["name"], order_by="modified desc", limit=1) if doc.vehicle and doc.trip_date else [] %}
{% if insp_rows %}
{% set insp = frappe.get_doc("Vehicle Inspection Log", insp_rows[0].name) %}
{% set insp_driver = (frappe.db.get_value("Employee", insp.driver, "employee_name") if insp.driver else None) or insp.driver_name_text or insp.driver or "" %}
{% set groups = {} %}
{% for row in (insp.items or []) %}
  {% set section = row.section or row.category or "Checklist | قائمة الفحص" %}
  {% if section not in groups %}{% set _ = groups.update({section: []}) %}{% endif %}
  {% set _ = groups[section].append(row) %}
{% endfor %}
<div class="insp-wrap" style="page-break-before: always; padding: 150px 45px 95px 45px; box-sizing: border-box; direction: ltr; text-align: left;">
<style>.inspection-print {
  color: #172033;
  font-family: "Ubuntu", "Amiri", Arial, sans-serif;
  font-size: 9px;
  line-height: 1.32;
}
.inspection-print table { width: 100%; border-collapse: collapse; }
.inspection-print .rtl, .inspection-print .company-ar, .inspection-print .document-title-ar { direction: rtl; }
.inspection-print .brand-table { border-bottom: 2px solid #174b72; margin-bottom: 8px; padding-bottom: 6px; }
.inspection-print .brand-table td { vertical-align: middle; padding: 4px; }
.inspection-print .brand-logo { width: 22%; }
.inspection-print .brand-logo img { display: block; max-width: 42mm; max-height: 18mm; width: auto; height: auto; }
.inspection-print .brand-copy { width: 54%; text-align: center; }
.inspection-print .company-ar { color: #0f2740; font-size: 15px; font-weight: 700; line-height: 1.2; }
.inspection-print .company-en { color: #526174; font-size: 9px; font-weight: 700; margin-top: 1px; }
.inspection-print .document-title { color: #174b72; font-size: 16px; font-weight: 800; letter-spacing: .6px; margin-top: 4px; }
.inspection-print .document-title-ar { color: #174b72; font-size: 12px; font-weight: 700; }
.inspection-print .document-code { width: 24%; text-align: right; }
.inspection-print .code-label { color: #8290a2; font-size: 7px; font-weight: 700; letter-spacing: .7px; }
.inspection-print .code-value { color: #172033; font-size: 11px; font-weight: 800; margin: 2px 0 5px; }
.inspection-print .status-pill { display: inline-block; background: #e8f3f8; color: #174b72; border: 1px solid #bdd6e3; border-radius: 10px; padding: 3px 7px; font-size: 6.8px; font-weight: 800; }
.inspection-print .meta-table { margin: 8px 0 9px; table-layout: fixed; }
.inspection-print .meta-table td { background: #f5f8fa; border: 1px solid #dce5ea; padding: 6px 8px; vertical-align: top; }
.inspection-print .label { display: block; color: #657589; font-size: 7px; font-weight: 700; letter-spacing: .15px; margin-bottom: 2px; }
.inspection-print .value { display: block; color: #172033; font-size: 9px; font-weight: 800; overflow-wrap: break-word; }
.inspection-print .checklist-heading { background: #174b72; color: #fff; border-radius: 4px 4px 0 0; padding: 5px 8px; font-size: 9px; font-weight: 800; letter-spacing: .45px; }
.inspection-print .checklist-heading table { color: #fff; }
.inspection-print .checklist-heading td { width: 50%; border: 0; padding: 0; }
.inspection-print .checklist-heading td:last-child { text-align: right; font-size: 10px; letter-spacing: 0; }
.inspection-print .section-title { background: #e9f1f5; color: #174b72; border: 1px solid #cbdce5; border-bottom: 0; padding: 4px 7px; font-size: 8px; font-weight: 800; page-break-after: avoid; }
.inspection-print .checklist-table { table-layout: fixed; margin-bottom: 5px; page-break-inside: avoid; }
.inspection-print .checklist-table th { background: #f7f9fa; color: #445267; border: 1px solid #cfd9df; padding: 3px 5px; font-size: 7px; font-weight: 800; text-align: center; line-height: 1.15; }
.inspection-print .checklist-table th span { font-size: 7.5px; direction: rtl; }
.inspection-print .checklist-table td { border: 1px solid #d8e0e5; padding: 3px 5px; vertical-align: middle; line-height: 1.18; }
.inspection-print .item-col { width: 54%; text-align: left; }
.inspection-print .state-col { width: 10%; text-align: center; }
.inspection-print .notes-col { width: 26%; text-align: left; }
.inspection-print .mark { font-size: 13px; font-weight: 800; line-height: 1; }
.inspection-print .mark.good { color: #17815e; background: #f1faf7; }
.inspection-print .mark.bad { color: #bb3d46; background: #fff6f6; }
.inspection-print .notes-table { margin-top: 7px; table-layout: fixed; page-break-inside: avoid; }
.inspection-print .notes-table td { width: 50%; border: 1px solid #d8e0e5; padding: 6px 8px; vertical-align: top; }
.inspection-print .note-value { display: block; min-height: 8mm; color: #26354a; font-size: 8px; }
.inspection-print .approval-table { margin-top: 8px; table-layout: fixed; page-break-inside: avoid; }
.inspection-print .approval-box { width: 48%; height: 42mm; border: 1px solid #cbd7df; border-radius: 5px; padding: 6px 8px; vertical-align: top; background: #fff; }
.inspection-print .approval-gap { width: 4%; border: 0; }
.inspection-print .approval-title { color: #174b72; border-bottom: 1px solid #e1e8ec; padding-bottom: 4px; font-size: 7.5px; font-weight: 800; letter-spacing: .35px; }
.inspection-print .approval-title table { color: #174b72; }
.inspection-print .approval-title td { width: 50%; border: 0; padding: 0; }
.inspection-print .approval-title td:last-child { text-align: right; direction: rtl; font-size: 8px; letter-spacing: 0; }
.inspection-print .signature-frame, .inspection-print .stamp-frame { height: 29mm; text-align: center; vertical-align: middle; overflow: hidden; padding: 2mm; }
.inspection-print .signature-frame img, .inspection-print .stamp-frame img { display: block; width: auto; height: auto; max-width: 100%; max-height: 28mm; margin: 0 auto; }
.inspection-print .stamp-frame img { max-width: 96%; max-height: 29mm; }
.inspection-print .signature-placeholder { color: #a6b0ba; font-size: 8px; padding-top: 12mm; }
.inspection-print .approval-name { border-top: 1px solid #aebac3; color: #34445a; font-size: 8px; font-weight: 700; padding-top: 3px; text-align: center; }
.inspection-print .footer-line { border-top: 1px solid #cbd7df; color: #6b7888; margin-top: 7px; padding-top: 5px; font-size: 7px; }
.inspection-print .footer-line span:last-child { float: right; }
.inspection-print .printed-driver-name { padding-top: 10mm; font-size: 13px; line-height: 1.6; font-weight: 700; color: #172033; text-align: center; }
.inspection-print .checklist-table, .inspection-print .notes-table, .inspection-print .approval-table { page-break-inside: avoid !important; }</style>
<div class="inspection-print">
  <table class="brand-table">
    <tr>
      <td class="brand-logo">
        {% if company_doc.company_logo %}<img src="{{ company_doc.company_logo | abs_url }}" alt="Company logo">{% endif %}
      </td>
      <td class="brand-copy">
        <div class="company-ar">{{ company_ar or company_en }}</div>
        <div class="company-en">{{ company_en }}</div>
        <div class="document-title">VEHICLE INSPECTION REPORT</div>
        <div class="document-title-ar">تقرير فحص المركبة</div>
      </td>
      <td class="document-code">
        <div class="code-label">REPORT NO.</div>
        <div class="code-value">{{ insp.inspection_no or insp.name }}</div>
        <div class="status-pill">DAILY SAFETY CHECK</div>
      </td>
    </tr>
  </table>

  <table class="meta-table">
    <tr>
      <td><span class="label">Inspection Date | تاريخ الفحص</span><span class="value">{{ frappe.utils.formatdate(insp.inspection_date, 'dd-MM-yyyy') if insp.inspection_date else "-" }}</span></td>
      <td><span class="label">Driver | السائق</span><span class="value">{{ insp_driver or "-" }}</span></td>
      <td><span class="label">Vehicle | المركبة</span><span class="value">{{ insp.vehicle or "-" }}{% if insp.vehicle_type %} &nbsp;{{ insp.vehicle_type }}{% endif %}{% if insp.odometer %} &nbsp;| {{ insp.odometer }} KM{% endif %}</span></td>
    </tr>
  </table>

  <div class="checklist-heading">
    <table><tr><td>INSPECTION CHECKLIST</td><td class="rtl">قائمة الفحص</td></tr></table>
  </div>

  {% for section, rows in groups.items() %}
    {% if rows %}
      <div class="section-title">{{ section }}</div>
      <table class="checklist-table">
        <thead>
          <tr>
            <th class="item-col">Inspection Item | بند الفحص</th>
            <th class="state-col good">Sound<br><span>سليم</span></th>
            <th class="state-col bad">Unsound<br><span>غير سليم</span></th>
            <th class="notes-col">Notes | ملاحظات</th>
          </tr>
        </thead>
        <tbody>
          {% for row in rows %}
            {% set is_unsound = "Unsound" in (row.status or "") %}
            <tr>
              <td class="item-col">{{ row.item or row.item_en or "" }}</td>
              <td class="state-col mark good">{% if not is_unsound %}✓{% endif %}</td>
              <td class="state-col mark bad">{% if is_unsound %}✓{% endif %}</td>
              <td class="notes-col">{{ row.notes or "" }}</td>
            </tr>
          {% endfor %}
        </tbody>
      </table>
    {% endif %}
  {% endfor %}

  <table class="notes-table">
    <tr>
      <td>
        <span class="label">Declaration | الإقرار</span>
        <span class="note-value">{{ insp.declaration or "I confirm that the above vehicle inspection is accurate. | أقر بصحة بيانات فحص المركبة أعلاه." }}</span>
      </td>
      <td>
        <span class="label">Overall Notes | ملاحظات عامة</span>
        <span class="note-value">{{ insp.overall_notes or "No additional notes | لا توجد ملاحظات إضافية" }}</span>
      </td>
    </tr>
  </table>

  <table class="approval-table">
    <tr>
      <td class="approval-box">
        <div class="approval-title"><table><tr><td>DRIVER ACKNOWLEDGEMENT</td><td class="rtl">إقرار السائق</td></tr></table></div>
        <div class="signature-frame">
          {% if insp.driver_signature %}<img src="{{ insp.driver_signature | abs_url }}" alt="Driver signature">{% else %}<div class="printed-driver-name">{{ insp_driver }}</div>{% endif %}
        </div>
        <div class="approval-name">{{ insp_driver }}</div>
      </td>
      <td class="approval-gap"></td>
      <td class="approval-box">
        <div class="approval-title"><table><tr><td>COMPANY APPROVAL</td><td class="rtl">اعتماد الشركة</td></tr></table></div>
        <div class="stamp-frame">
          {% if insp.company_stamp %}<img src="{{ insp.company_stamp | abs_url }}" alt="Company stamp">{% else %}<div class="signature-placeholder">Official Stamp | الختم الرسمي</div>{% endif %}
        </div>
      </td>
    </tr>
  </table>

  <div class="footer-line">
    <span>{{ company_en }}</span>
    <span>{% if company_phone %}Tel: {{ company_phone }}{% endif %}{% if company_phone and reg_no %} &nbsp;|&nbsp; {% endif %}{% if reg_no %}CR: {{ reg_no }}{% endif %}</span>
  </div>
</div>
</div>
{% endif %}
